/bin/bash -lc "python - <<'PY'
import json
ps=json.load(open('judge-input.json'))['finalCanvases']
for ix in [0,12]:
 p=ps[ix];print('POINT',p['pointId'])
 for d in p['canvas']['diagrams']:
  if ix==0 and d['id']"'!='"'central':continue
  print('DIAGRAM',d['id']);print('\\n'.join(f'{i}: {s}' for i,s in enumerate(d['ascii'].splitlines(),1)))
 print('EDGES',json.dumps(p['canvas']['edges']))
print('CHECKS')
count=lines=0
for p in ps:
 ds={d['id']:d for d in p['canvas']['diagrams']}; count+=len(ds)
 adj={k:set() for k in ds}; bad=[]; overlaps=[]
 for e in p['canvas']['edges']:
  for end in ['source','target']:
   q=e[end]
   if q['diagram'] not in ds or not 1<=q['line']<=len(ds[q['diagram']]['ascii'].splitlines()):bad.append(q)
  adj[e['source']['diagram']].add(e['target']['diagram']);adj[e['target']['diagram']].add(e['source']['diagram'])
 seen=set();todo=['central']
 while todo:
  n=todo.pop()
  if n not in seen:seen.add(n);todo.extend(adj[n]-seen)
 boxes=[]
 for d in ds.values():
  ls=d['ascii'].splitlines();lines+=len(ls);x=d['position']['column'];y=d['position']['row'];w=max(map(len,ls));h=len(ls);boxes.append((d['id'],x,y,x+w,y+h))
 for i,a in enumerate(boxes):
  for b in boxes[i+1:]:
   if a[1]<b[3] and b[1]<a[3] and a[2]<b[4] and b[2]<a[4]:overlaps.append((a[0],b[0]))
 print(p['pointId'],'connected',len(seen)==len(ds),'bad',bad,'overlaps',overlaps,'bounds',max(b[3] for b in boxes),max(b[4] for b in boxes))
print('TOTAL',count,lines)
PY"

